        INSERT INTO learn_questions (id, question_text, options_json, correct_answer, question_type, subject, chapter, marks, model_answer, marking_scheme_json, case_passage, explanation, difficulty, is_verified)
        VALUES
        ('12031111-0000-4000-8000-000000000001', 'Innermost nutritive wall layer of a microsporangium whose cells often have dense cytoplasm and >1 nucleus is:', '{"A":"Epidermis","B":"Endothecium","C":"Tapetum","D":"Middle layer"}'::jsonb, 'C', 'MCQ', 'Biology', 'Sexual Reproduction in Flowering Plants', 1, 'Tapetum nourishes developing pollen grains and secretes sporopollenin/pollenkit.', NULL, NULL, 'Tapetum nourishes developing pollen grains and secretes sporopollenin/pollenkit.', 'EASY', true),
        ('12031111-0000-4000-8000-000000000002', 'Exine of pollen grains is extraordinarily resistant to high temperatures, strong acids, and enzymes due to:', '{"A":"Cellulose","B":"Sporopollenin","C":"Pectin","D":"Suberin"}'::jsonb, 'B', 'MCQ', 'Biology', 'Sexual Reproduction in Flowering Plants', 1, 'Sporopollenin is the most resistant organic biological material known (preserved as fossils).', NULL, NULL, 'Sporopollenin is the most resistant organic biological material known (preserved as fossils).', 'EASY', true),
        ('12031111-0000-4000-8000-000000000003', 'A typical mature Polygonum-type angiosperm embryo sac at fertilisation is:', '{"A":"7-celled, 7-nucleate","B":"7-celled, 8-nucleate","C":"8-celled, 7-nucleate","D":"8-celled, 8-nucleate"}'::jsonb, 'B', 'MCQ', 'Biology', 'Sexual Reproduction in Flowering Plants', 1, '3 antipodals + 2 synergids + 1 egg + 1 large central cell with 2 polar nuclei.', NULL, NULL, '3 antipodals + 2 synergids + 1 egg + 1 large central cell with 2 polar nuclei.', 'EASY', true),
        ('12031111-0000-4000-8000-000000000004', 'Cleistogamous flowers (e.g., Viola, Oxalis, Commelina) ensure:', '{"A":"Cross-pollination only","B":"Assured seed-set even in complete absence of pollinators via self-pollination","C":"Sterility","D":"Wind dispersal"}'::jsonb, 'B', 'MCQ', 'Biology', 'Sexual Reproduction in Flowering Plants', 1, 'Never open at all -> invariant autogamy.', NULL, NULL, 'Never open at all -> invariant autogamy.', 'EASY', true),
        ('12031111-0000-4000-8000-000000000005', 'Persistent remnant of nucellus seen in seeds of black pepper and beet is called:', '{"A":"Endosperm","B":"Perisperm","C":"Scutellum","D":"Epicotyl"}'::jsonb, 'B', 'MCQ', 'Biology', 'Sexual Reproduction in Flowering Plants', 1, 'Residual diploid maternal nucellus = Perisperm.', NULL, NULL, 'Residual diploid maternal nucellus = Perisperm.', 'EASY', true),
        ('12031111-0000-4000-8000-000000000006', 'Assertion (A): In wind-pollinated grasses and maize, flowers are small, dull, lack nectar, and produce enormous dry non-sticky pollen.
